def lr_parse(tokens, ACTION, GOTO, rules):
    stack = [0]  # 상태 스택
    tokens = tokens + ['$']
    i = 0
    while True:
        s, a = stack[-1], tokens[i]
        act = ACTION.get((s, a))
        if act is None:
            raise SyntaxError(a)  # 빈칸 = 오류
        kind, val = act
        if kind == 'shift':
            stack.append(val)  # 다음 상태 push
            i += 1
        elif kind == 'reduce':
            lhs, rhs_len = rules[val]  # 규칙 번호
            if rhs_len:
                del stack[-rhs_len:]  # 우변 길이만큼 pop
            stack.append(GOTO[(stack[-1], lhs)])
            print('reduce', val)  # 우측 유도 역순
        else:
            return True  # accept
